/ {
	/* Define an emulated I2C bus controller */
	i2c_emul_0: i2c_emul_0 {
		compatible = "zephyr,i2c-emul-controller";
		#address-cells = <1>;
		#size-cells = <0>;
		status = "okay";

		/* Place the ADT7420 emulator as a child of the emulated I2C bus */
		adt7420_default_test: adt7420@48 {
			compatible = "adi,adt7420";
			reg = <0x48>;
			op-mode = "one-shot";
			set-resolution = <16>;
			set-comparator-mode;
		};
	};

	aliases {
		adt7420 = &adt7420_default_test;
		/* Alias i2c0 to the emulated bus for compatibility with existing code */
		i2c0 = &i2c_emul_0;
	};
};
